with ins as (
  insert into public.recipes (title, instructions, image_url, cuisine, diet, status, author_id)
  select 'Pouding chomeur', 'In a large bowl, with an electric mixer, mix the butter and sugar till the mix is light.
Add eggs and vanilla and mix.
In another bowl, mix flour and baking powder.
Alternate flour mix and milk to the butter mix.
Pour into a 13 inch by 9 inch greased pan.
MAPLE SAUCE.
